SELECT DATE_FORMAT(opened_date, 'yyyy-MM') AS opened_month, QUARTER(opened_date) AS opened_quarter, SUM(CASE WHEN city = 'London' THEN sqft ELSE 0 END) AS london_sqft, ROUND(AVG(sqft), 2) AS avg_sqft FROM stores WHERE UPPER(store_name) LIKE '%ALL%' AND store_name LIKE '%Siam%' AND city = 'London' GROUP BY DATE_FORMAT(opened_date, 'yyyy-MM'), QUARTER(opened_date) ORDER BY 3 DESC, opened_month, opened_quarter LIMIT 50
